<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'@/services/api';const props=withDefaults(defineProps<{tourSlug?:string;editing?:boolean}>(),{tourSlug:'',editing:false});const tour=ref<any>(null);const departures=ref<any[]>([]);onMounted(async()=>{if(!props.tourSlug)return;tour.value=await api(`/api/public/travel/tours/${props.tourSlug}`).catch(()=>null);if(tour.value)departures.value=await api<any[]>(`/api/public/travel/tours/${props.tourSlug}/departures`).catch(()=>[])});const next=computed(()=>departures.value.find(i=>i.availableSeats>0));</script><template><aside class="booking"><template v-if="tour"><span>BOOK NOW</span><h3>{{ tour.name }}</h3><strong>{{ new Intl.NumberFormat('en-US',{style:'currency',currency:tour.currency}).format(tour.adultPrice) }}</strong><p v-if="next">Next departure: {{ new Date(next.startsAt).toLocaleDateString('en-US') }} · {{ next.availableSeats }} seats</p><RouterLink v-if="!editing" :to="`/travel/${tour.slug}`">Check availability</RouterLink></template><template v-else><h3>Booking panel</h3><p>Select the slug of a published tour.</p></template></aside></template><style scoped>.booking{padding:25px;border:1px solid #d6e3e1;border-radius:20px;background:white;box-shadow:0 16px 45px #14595615}.booking span{font-size:.7rem;color:#087f7b;font-weight:900;letter-spacing:.15em}.booking h3{font-size:1.4rem}.booking strong{font-size:1.8rem}.booking p{color:#617572}.booking a{display:block;padding:12px;border-radius:11px;background:#087f7b;color:white;text-align:center;font-weight:900;text-decoration:none}</style>
